import type { AtRule } from "postcss";
/**
 * Asks whether whitespace written behind an at-rule's name changes what Less reads the at-rule as.
 *
 * Less takes `@import` and `@plugin` as directives only where whitespace stands behind the lower-case name. `@import(reference) "x"`, `@import"x"` and one with a comment right behind the name it prints through as text, and whitespace written into them makes them directives; every other at-rule it reads the same way in both spellings. An upper-case name Less refuses in both, and is read all the same: `at-rule-name-case` lowercases it within the same run, so the answer would otherwise hang on the order the rules are listed in.
 * @param atRule - The at-rule.
 * @returns True where a rule writing whitespace behind the name would change the stylesheet's meaning.
 */
export declare function readsWhitespaceBehindAtRuleName(atRule: AtRule): boolean;
